#[cfg(test)]
mod tests {
    use super::*;

    #[test]
    fn listener_selection_uses_priority_then_stable_id() {
        let mut scene = AuthoringScene::new();
        let listener_type = ComponentTypeId::new(engine::scene_bridge::AUDIO_LISTENER_COMPONENT);
        let high_a = EntityId::generate();
        let high_b = EntityId::generate();
        let low = EntityId::generate();
        let expected = if high_a.as_str() < high_b.as_str() {
            high_a.clone()
        } else {
            high_b.clone()
        };
        let mut transaction = Transaction::begin(&scene);
        for (id, priority) in [
            (high_a, 7_i64),
            (high_b, 7_i64),
            (low, 3_i64),
        ] {
            transaction.apply(AuthoringCommand::CreateEntity {
                id: id.clone(),
                name: "listener".to_owned(),
                parent: None,
            });
            transaction.apply(AuthoringCommand::AddComponent {
                entity: id,
                component_type: listener_type.clone(),
                value: Value::Object(std::collections::BTreeMap::from([
                    ("enabled".to_owned(), Value::Bool(true)),
                    ("priority".to_owned(), Value::I64(priority)),
                ])),
            });
        }
        transaction
            .commit(&mut scene)
            .expect("listener fixture must commit");

        assert_eq!(active_game_listener(&scene), Some(expected));
    }

    #[test]
    fn transient_audition_controls_do_not_dirty_the_scene() {
        let directory = tempfile::tempdir().expect("temporary scene directory");
        let path = directory.path().join("audio.scene.json");
        std::fs::write(&path, r#"{"schema_version":1,"entities":[]}"#)
            .expect("empty scene fixture writes");
        let mut session = EditorSession::empty_behavior_tree();
        session.open_scene(path).expect("scene fixture opens");
        let mut app = EditorApp::new(session);
        let revision = app.session.document_revision();
        let selected = EntityId::generate();

        app.handle_audio_inspector_action(
            &selected,
            &Value::Null,
            AudioInspectorAction::UseSceneViewListener,
        );
        app.handle_audio_inspector_action(
            &selected,
            &Value::Null,
            AudioInspectorAction::UseGameListener,
        );
        app.handle_audio_inspector_action(&selected, &Value::Null, AudioInspectorAction::Stop);

        assert_eq!(app.session.document_revision(), revision);
        assert!(!app.session.is_dirty());
    }
}
